import numpy as np

class ModelNoise:
    def __init__(self,Bd,sigma_a,rng):


        ## Model Noise ##
        # This noise is user induced to account for errors in acceleations
        # and does not include the natural noise generated by the difference b/w 
        # the simulation and the model


        # Noise Covariance due to acceleration term
        Qa = (sigma_a**2) * Bd @ Bd.T

        # Noise Covariance
        self.Q = Qa
        self.rng = rng

        # Eigenvalues and Eigenvectors
        mu, D = np.linalg.eigh(self.Q)
        mu = mu * (mu > 0)
        self.L = D * np.sqrt(mu)

    def sample(self):

        # Get a value of noise w_k

        # Random unit vector with mean = 0, variance = 1
        r = self.rng.standard_normal(self.Q.shape[0])

        # Noise
        w = self.L @ r

        return w
        # Note: rng is defined in the Main to get same seed everywhere and to get same generator